  hero:{eyebrow:'Welcome',heading:'A clear, compassionate headline',text:'Add a short introduction that helps visitors understand this page.',primary_label:'Book an appointment',primary_url:'/book',primary_action:'internal',primary_style:'primary',primary_icon:'calendar',primary_icon_position:'right',primary_target:'_self',primary_visibility:'show',secondary_label:'Learn more',secondary_url:'/about',secondary_action:'internal',secondary_style:'outline',secondary_icon:'arrow',secondary_icon_position:'right',secondary_target:'_self',secondary_visibility:'show'},
  text:{eyebrow:'Overview',heading:'Rich text section',body:'Double-click this paragraph to replace it with your page content.'},
