 const c=section.content,p=section.presentation||{},r=resolvedPresentation(p,viewport),cls=`cms-section cms-${section.type} cms-bg-${r.background||'ivory'} cms-align-${r.alignment||'left'} cms-space-${r.spacing||'normal'} cms-font-${r.font_family||'site'} cms-size-${r.font_size||'normal'} cms-weight-${r.font_weight||'regular'} cms-emphasis-${r.emphasis||'none'} cms-color-${r.text_color||'default'} cms-leading-${r.line_height||'normal'} cms-layout-${r.layout||'block'} cms-columns-${r.columns||'1'} cms-items-${r.content_alignment||'start'} cms-gap-${r.gap||'normal'} cms-margin-${r.margin||'none'} cms-radius-${r.radius||'none'} cms-shadow-${r.shadow||'none'} cms-pattern-${r.background_pattern||'none'} cms-contour-${r.contour||'none'} ${editing?'cms-editable-section':''} ${selected?'selected':''} ${!section.is_visible?'cms-hidden-draft':''}`,inner=`container cms-width-${r.width||'normal'}`,shell={className:cls,style:sectionStyle(r),onClick:onSelect,onDragOver:(event:React.DragEvent)=>editing&&event.preventDefault(),onDrop:(event:React.DragEvent)=>{if(!editing)return;event.preventDefault();event.stopPropagation();onDrop(event.dataTransfer.getData('text/cms-section'))}};
 const edit=(tag:string,field:string,label:string)=><EditableText tag={tag} sectionKey={section.section_key} field={field} label={label} value={c[field]} marks={c[`${field}_marks`]} style={p.text_styles?.[field]} editing={editing} active={activeTarget?.sectionKey===section.section_key&&activeTarget?.field===field} onEdit={onEdit} onRange={onRange} onLinkSelect={onLinkSelect} onChange={onTextChange} onFinish={onFinish}/>,button=(prefix:string,label:string)=><EditableButton prefix={prefix} label={label} sectionKey={section.section_key} content={c} presentation={p} editing={editing} active={activeTarget?.sectionKey===section.section_key&&activeTarget?.field===`${prefix}_label`} onEdit={onEdit} onChange={onTextChange} onFinish={onFinish}/>,eyebrow=edit('span','eyebrow','Eyebrow text'),heading=(level='h2')=>edit(level,'heading','Heading'),tools=editing&&<SectionTools sectionKey={section.section_key} type={section.type} visible={section.is_visible} canMoveUp={canMoveUp} canMoveDown={canMoveDown} onSelect={onSelect} onMove={onMove} onDuplicate={onDuplicate} onToggle={onToggle} onDelete={onDelete}/>;
 const items=(c.items||[]).filter((item:any)=>editing||item.is_visible!==false);
 const componentProps=(item:any,index:number)=>{if(!editing)return{};const label=componentLabel(section.type,item,index),select=(event:React.SyntheticEvent)=>{event.preventDefault();event.stopPropagation();onComponentSelect(item.key)};return{'data-cms-component':item.key,role:'button',tabIndex:0,'aria-label':`Select ${label} component`,onClick:select,onKeyDown:(event:React.KeyboardEvent)=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();select(event)}}}},componentClass=(item:any,base='')=>`${base} ${editing?'cms-editable-component':''} ${selectedItemKey===item.key?'cms-component-selected':''} ${item.is_visible===false?'cms-component-hidden':''}`;
 if(section.type==='hero')return <section {...shell}>{tools}<div className={inner}>{eyebrow}{heading('h1')}{edit('p','text','Supporting text')}<div className="hero-actions">{c.primary_label&&button('primary','Primary button text')} {c.secondary_label&&button('secondary','Secondary button text')}</div></div></section>;
