 if(section.type==='image_text')return <section {...shell}>{tools}<div className={`${inner} cms-image-grid cms-image-${r.image_alignment||'left'} cms-image-width-${r.image_width||'medium'}`}><figure><SafeImage content={c} presentation={r} editing={editing} selected={Boolean(selectedImage&&!selectedImage.itemKey)} label="supporting image" onSelect={()=>onImageSelect()}/>{edit('figcaption','caption','Image caption')}</figure><div>{eyebrow}{heading()}{edit('p','text','Supporting text')}</div></div></section>;
