 if(section.type==='career_timeline')return <section {...shell}>{tools}<div className={inner}>{eyebrow}{heading()}{edit('p','text','Supporting text')}<ol className="cms-timeline">{items.map((item:any,index:number)=><li className={componentClass(item)} {...componentProps(item,index)} key={item.key||`${item.year}-${item.heading}`}><time>{item.year}</time><div><h3>{item.heading}</h3><p>{item.text}</p></div></li>)}</ol></div></section>;
