 if(section.type==='gallery')return <section {...shell}>{tools}<div className={inner}>{eyebrow}{heading()}{edit('p','text','Supporting text')}<div className="cms-gallery-grid">{items.map((item:any,index:number)=><figure className={componentClass(item)} {...componentProps(item,index)} key={item.key||item.image_alt}><SafeImage content={item} presentation={r} editing={editing} selected={selectedImage?.itemKey===item.key} label={`gallery image ${index+1}`} onSelect={()=>onImageSelect(item.key)}/><figcaption>{item.caption}</figcaption></figure>)}</div></div></section>;
