function EditableButton({prefix,label,sectionKey,content,presentation,editing,active,onEdit,onChange,onFinish}:{prefix:string;label:string;sectionKey:string;content:any;presentation:any;editing:boolean;active:boolean;onEdit:(field:string,label:string)=>void;onChange:(field:string,value:string)=>void;onFinish:()=>void}){const field=`${prefix}_label`,visibility=content[`${prefix}_visibility`]||'show',icon=content[`${prefix}_icon`]||'arrow',iconPosition=content[`${prefix}_icon_position`]||'right',style=content[`${prefix}_style`]||'primary',custom=presentation.button_styles?.[prefix]||{},symbol=buttonSymbol(icon),cls=style==='outline'?'btn btn-outline-primary':style==='light'?'btn btn-light':'btn btn-primary';if(visibility==='hide'&&!editing)return null;if(!editing)return <SafeLink label={content[field]} url={content[`${prefix}_url`]} style={style} icon={icon} iconPosition={iconPosition} visibility={visibility} target={content[`${prefix}_target`]} customStyle={custom}/>;return <span className={`cms-button-slot cms-button-${custom.alignment||'left'} ${visibility==='hide'?'cms-button-hidden':''}`}><span role="button" tabIndex={0} aria-label={`Edit ${label}`} className={`${cls} cms-editable-button ${active?'selected':''}`} style={buttonStyle(custom)} onClick={event=>{event.preventDefault();event.stopPropagation();onEdit(field,label)}}>{iconPosition==='left'&&symbol}<EditableText tag="span" sectionKey={sectionKey} field={field} label={label} value={content[field]} style={presentation.text_styles?.[field]} editing active={active} onEdit={onEdit} onRange={()=>undefined} onLinkSelect={()=>undefined} onChange={onChange} onFinish={onFinish}/>{iconPosition!=='left'&&symbol}</span></span>}

